import os
import torch


class Config:
    """
    Configuration for the Custom Wide Split-Attention Network experiment.
    """

    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_21"

    # Metadata Paths (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Image Directories (Relative to INPUT_DIR as per metadata)
    # Metadata contains paths like 'train/id.jpg', so we just need INPUT_DIR

    # Output Paths
    SUBMISSION_DIR = os.path.join(WORKING_DIR, "submission")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Reproducibility
    # ==========================================
    # Homogeneous Seed Averaging
    SEEDS = [0, 1, 2, 3, 4]

    # ==========================================
    # Data Configuration
    # ==========================================
    IMAGE_SIZE = (32, 32)
    INPUT_CHANNELS = 3
    NUM_CLASSES = 1

    # Preprocessing
    # Images are loaded in [0, 1] range (ToTensor).
    # No Mean/Std normalization is applied as per "normalized to [0, 1]" requirement.

    # Debugging / Development
    # Set to a small integer (e.g., 100) to train on a subset for quick pipeline checks.
    # Set to None for full training.
    DEBUG_SUBSET_SIZE = None

    # ==========================================
    # Model Architecture
    # ==========================================
    # Custom Wide Split-Attention Network
    # Backbone: 3 Stages, preserving 8x8 resolution
    # Channels: Super-Wide Configuration
    STAGES_CHANNELS = [64, 128, 256]

    # Split-Attention Block Parameters
    RADIX = 2  # Number of splits within a group
    CARDINALITY = 1  # Number of groups (1 = ResNet-like width, >1 = ResNeXt-like)

    # Head Configuration
    # Multi-Scale Aggregation: Concatenates GAP(Stage2) and GAP(Stage3)

    # ==========================================
    # Training Configuration
    # ==========================================
    EPOCHS = 20
    BATCH_SIZE = 128

    # Optimizer: AdamW
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2

    # Scheduler: Cosine Annealing
    # T_max matches EPOCHS
    SCHEDULER_T_MAX = 20
    SCHEDULER_ETA_MIN = 1e-6

    # ==========================================
    # Augmentation
    # ==========================================
    # Light augmentation only
    AUG_HFLIP_PROB = 0.5
    AUG_VFLIP_PROB = 0.5

    # ==========================================
    # Hardware
    # ==========================================
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures necessary working directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories on import
Config.setup()
